import * as THREE from '../three.module.js';
import {rng} from '../physics.js';
import {createHuman} from './PlayerBody.js';
export class CrowdLODController {
 constructor(scene,camera,{density=12,nearDistance=73,midDistance=88}={}){this.scene=scene;this.camera=camera;this.nearDistance=nearDistance;this.midDistance=midDistance;this.people=[];this.clock=0;this.lastUpdate=-1;this.stats={near:0,mid:0,far:0};const random=rng(92617),shirt=['#eef0df','#174561','#9b443c','#d1af4e','#5c7475','#273b44','#9d7c96','#e3c9b1'],skins=['#edc3a0','#bf8964','#8d593e','#513626'];
 for(let sector=0;sector<36;sector++)for(let tier=0;tier<3;tier++)for(let n=0;n<density;n++){const a=sector/36*Math.PI*2+(n-(density-1)/2)*.009,r=73+tier*4;this.people.push({x:Math.sin(a)*r,z:Math.cos(a)*r-10,y:2.6+tier*2.6,scale:.85+random()*.3,width:.9+random()*.25,phase:random()*6.28,shirt:new THREE.Color(shirt[Math.floor(random()*shirt.length)]),skin:new THREE.Color(skins[Math.floor(random()*skins.length)]),sprite:Math.floor(random()*16),hat:random()<.3});}
 const sphere=new THREE.SphereGeometry(1,12,8),lowSphere=new THREE.SphereGeometry(1,6,5);this.parts={};const specs={torso:[sphere,'#fff'],head:[sphere,'#fff'],hair:[sphere,'#302a23'],nose:[sphere,'#fff'],armL:[sphere,'#fff'],armR:[sphere,'#fff'],legL:[sphere,'#24424a'],legR:[sphere,'#24424a'],midTorso:[lowSphere,'#fff'],midHead:[lowSphere,'#fff'],midArms:[lowSphere,'#fff']};
 for(const [key,[geometry,color]] of Object.entries(specs)){const batch=new THREE.InstancedMesh(geometry,new THREE.MeshStandardMaterial({color,roughness:1}),this.people.length);batch.instanceMatrix.setUsage(THREE.DynamicDrawUsage);batch.frustumCulled=false;scene.add(batch);this.parts[key]=batch;}
 this.cards=[];this.atlasReady=false;if(typeof document.createElementNS==='function'){new THREE.TextureLoader().load('./assets/crowd-atlas.png',texture=>{texture.colorSpace=THREE.SRGBColorSpace;texture.anisotropy=4;for(let i=0;i<16;i++){const geometry=new THREE.PlaneGeometry(.8,1.7),uv=geometry.getAttribute('uv');for(let j=0;j<uv.count;j++)uv.setXY(j,(i%8+(uv.getX(j)*.98+.01))/8,(1-Math.floor(i/8)+(uv.getY(j)*.98+.01))/2);const card=new THREE.InstancedMesh(geometry,new THREE.MeshBasicMaterial({map:texture,alphaTest:.42,side:THREE.DoubleSide}),this.people.length);card.frustumCulled=false;scene.add(card);this.cards.push(card);}this.atlasReady=true;this.lastUpdate=-1;},undefined,()=>{this.atlasReady=false;});}
 this.dummy=new THREE.Object3D();this.flags=[];for(const a of [.35,2.8,4.8]){const x=Math.sin(a)*68,z=Math.cos(a)*68-10;const pole=new THREE.Mesh(new THREE.CylinderGeometry(.035,.035,3,8),new THREE.MeshStandardMaterial({color:'#bcc7c7'}));pole.position.set(x,1.5,z);scene.add(pole);const flag=new THREE.Mesh(new THREE.PlaneGeometry(1.7,.85,12,4),new THREE.MeshStandardMaterial({color:'#d8f58e',side:THREE.DoubleSide,roughness:.8}));flag.position.set(x+.85,2.55,z);scene.add(flag);this.flags.push(flag);}
 this.staff=[];for(const [x,z,role] of [[-41,-48,'staff'],[45,-42,'staff'],[-33,45,'photo']]){const h=createHuman(scene,x,z,{shirt:new THREE.MeshStandardMaterial({color:role==='staff'?'#e0a437':'#60716d'})});this.staff.push(h);if(role==='photo'){h.g.rotation.y=Math.PI;h.limbs[2].rotation.x=-1.1;h.limbs[3].rotation.x=-1.1;const cameraProp=new THREE.Mesh(new THREE.BoxGeometry(.16,.12,.15),new THREE.MeshStandardMaterial({color:'#152125'}));cameraProp.position.set(0,1.42,.30);h.g.add(cameraProp);}}
 }
 update(dt,intensity){this.clock+=dt;if(this.clock-this.lastUpdate<1/12)return;this.lastUpdate=this.clock;const counts=Object.fromEntries(Object.keys(this.parts).map(k=>[k,0])),cardCounts=Array(16).fill(0);this.stats={near:0,mid:0,far:0};
 const put=(key,p,dx,dy,dz,sx,sy,sz,color)=>{const m=this.parts[key],i=counts[key]++,d=this.dummy,angle=Math.atan2(-p.x,-10-p.z);d.position.set(p.x+Math.cos(angle)*dx+Math.sin(angle)*dz,p.y+dy*p.scale,p.z-Math.sin(angle)*dx+Math.cos(angle)*dz);d.rotation.set(0,angle,0);d.scale.set(sx*p.width,sy*p.scale,sz);d.updateMatrix();m.setMatrixAt(i,d.matrix);if(color)m.setColorAt(i,color);};
 const eye=this.camera.getWorldPosition(new THREE.Vector3());let personIndex=0;for(const p of this.people){if(personIndex++%(this.densityStride||1))continue;const distance=Math.hypot(p.x-eye.x,p.z-eye.z),wave=Math.sin(this.clock*3+p.phase),rise=Math.max(0,intensity-.4)*.35;
 if(distance<this.nearDistance){this.stats.near++;put('torso',p,0,.78+rise,0,.20,.28,.12,p.shirt);put('head',p,0,1.18+rise,0,.10,.14,.10,p.skin);put('hair',p,0,1.28+rise,-.01,.103,p.hat?.08:.035,.102);put('nose',p,0,1.18+rise,.11,.028,.035,.04,p.skin);for(const side of [-1,1]){const raised=intensity>.4;put(side<0?'armL':'armR',p,side*(raised?.28:.24),(raised?1.22+wave*.08:.73)+rise,.10,.055,raised?.25:.20,.054,p.skin);put(side<0?'legL':'legR',p,side*.10,.32,-.01,.075,.30,.09);}}
 else if(distance<this.midDistance||!this.atlasReady){this.stats.mid++;put('midTorso',p,0,.72+rise,0,.19,.34,.12,p.shirt);put('midHead',p,0,1.17+rise,0,.105,.14,.105,p.skin);put('midArms',p,0,.80+rise+intensity*.24,.04,.30,.085,.075,p.shirt);}
 else {this.stats.far++;const d=this.dummy;d.position.set(p.x,p.y+.76+rise,p.z);d.rotation.set(0,Math.atan2(eye.x-p.x,eye.z-p.z),0);d.scale.set(p.width,p.scale,1);d.updateMatrix();this.cards[p.sprite].setMatrixAt(cardCounts[p.sprite]++,d.matrix);}}
 for(const [key,m] of Object.entries(this.parts)){m.count=counts[key];m.instanceMatrix.needsUpdate=true;if(m.instanceColor)m.instanceColor.needsUpdate=true;}for(let i=0;i<this.cards.length;i++){this.cards[i].count=cardCounts[i];this.cards[i].instanceMatrix.needsUpdate=true;}
 for(const flag of this.flags){const pos=flag.geometry.attributes.position;for(let i=0;i<pos.count;i++)pos.setZ(i,Math.sin(pos.getX(i)*4+this.clock*3)*.10*(pos.getX(i)+.85));pos.needsUpdate=true;flag.geometry.computeVertexNormals();}
 }
}
